private static byte[] toHexDigits(final byte[] address) {
    final byte[] digits = new byte[address.length * 2];
    int digitInd = 0;
    for (int ipByte : address) {
        digits[digitInd++] = HEX_DIGITS[(ipByte >> 4) & 0x0F];
        digits[digitInd++] = HEX_DIGITS[ipByte & 0x0F];
    }
    return digits;
}
